      'import silk.layout { Layout as LayoutValue }\n\n/// Allocates owned storage through an explicitly provided implementation.\npub struct OutOfMemory {}\n\npub effect fn outOfMemory() -> never ! OutOfMemory {\n  fail OutOfMemory {}\n}\n\npub service Allocator {\n  effect fn allocate(layout: LayoutValue) -> Allocation ! OutOfMemory ? &mut Allocator\n}\n\n/// Constructs the process-backed allocation provider.\npub struct SystemAllocator {}\n\npub fn make() -> SystemAllocator {\n  return SystemAllocator {}\n}\n\neffect fn allocate(self: &mut SystemAllocator, layout: LayoutValue) -> Allocation ! OutOfMemory {\n  return run Intrinsic.systemAllocationAcquire(move layout)\n}\n\nimpl Allocator for SystemAllocator {\n  allocate: SystemAllocator.allocate\n}\n\n/// Failure to commit one complete stream message.\npub struct StreamWriteFailure {}\n\nimpl Report for StreamWriteFailure {}\n\n/// Portable complete-message output contract.\npub service StandardStreams {\n  effect fn writeAll(\n    destination: bool,\n    bytes: &[u8]\n  ) -> () ! StreamWriteFailure ? &mut StandardStreams\n}\n\n/// Process-backed standard-stream provider.\npub struct NativeStandardStreams {}\n\npub fn stdout() -> bool {\n  return false\n}\n\npub fn stderr() -> bool {\n  return true\n}\n\npub fn native() -> NativeStandardStreams {\n  return NativeStandardStreams {}\n}\n\neffect fn nativeWriteAll(\n  self: &NativeStandardStreams,\n  destination: bool,\n  bytes: &[u8]\n) -> () ! StreamWriteFailure {\n  return run Intrinsic.standardStreamWrite(destination, bytes)\n}\n\nimpl StandardStreams for NativeStandardStreams {\n  writeAll: NativeStandardStreams.nativeWriteAll\n}\n\n/// Builds one complete-write service effect.\npub effect fn send(\n  destination: bool,\n  bytes: &[u8]\n) -> () ! StreamWriteFailure ? &mut StandardStreams {\n  return run StandardStreams.writeAll(move destination, bytes)\n}\n',
