      '/// Static addition contract for primitive integer values.\n///\n/// Interfaces select compiler-known operations during specialization. They do not create\n/// effect requirements, provider slots, or runtime dispatch.\npub interface Integer<T> {\n  fn add(left: T, right: T) -> T\n}\n\nimpl Integer<u8> for u8 { add: Intrinsic.u8Add }\nimpl Integer<u16> for u16 { add: Intrinsic.u16Add }\nimpl Integer<u32> for u32 { add: Intrinsic.u32Add }\nimpl Integer<u64> for u64 { add: Intrinsic.u64Add }\nimpl Integer<usize> for usize { add: Intrinsic.usizeAdd }\nimpl Integer<i8> for i8 { add: Intrinsic.i8Add }\nimpl Integer<i16> for i16 { add: Intrinsic.i16Add }\nimpl Integer<i32> for i32 { add: Intrinsic.i32Add }\nimpl Integer<i64> for i64 { add: Intrinsic.i64Add }\nimpl Integer<isize> for isize { add: Intrinsic.isizeAdd }\n\n/// Adds two values using the concrete integer operation selected during specialization.\npub fn add<T: Integer>(left: T, right: T) -> T {\n  return left + right\n}\n',
