      "// Canonical recoverable outcome members. The compiler's Option<T> is represented transparently by the\n// structural union Some<T> | None; the named declaration is its source-navigation anchor.\n\npub struct Some<T> {\n  value: T\n}\n\npub struct None {}\n\npub struct Option<T> {\n  value: Some<T> | None\n}\n\n/// Constructs an absent optional value.\npub fn none<T>() -> Option<T> {\n  return None {}\n}\n\n/// Constructs a present optional value.\npub fn some<T>(value: T) -> Option<T> {\n  return Some<T> { value: move value }\n}\n\n/// Applies a transform to a present value and keeps an absent value absent.\npub fn map<T, U>(self: Option<T>, transform: once fn(T) -> U) -> Option<U> {\n  return match move self {\n    Some<T> { value } => some<U>(transform(move value))\n    None {} => none<U>()\n  }\n}\n\n/// Continues a present value with a transform that itself answers with an Option, so the\n/// outcome stays one Option deep instead of nesting.\npub fn flatMap<T, U>(self: Option<T>, transform: once fn(T) -> Option<U>) -> Option<U> {\n  return match move self {\n    Some<T> { value } => transform(move value)\n    None {} => none<U>()\n  }\n}\n\n/// Returns the present value, or the fallback value when the option is absent.\n///\n/// Only the absent arm consumes the fallback. The present arm releases it, so exactly one of the\n/// two owned values leaves this call and the other drops.\npub fn unwrapOr<T>(self: Option<T>, fallback: T) -> T {\n  return match move self {\n    Some<T> { value } => keepPresent<T>(move value, move fallback)\n    None {} => move fallback\n  }\n}\n\n/// Releases the fallback that a present value never needed. A match arm is one expression, so the\n/// arm that must both drop and produce delegates to this helper.\nfn keepPresent<T>(present: T, unused: T) -> T {\n  drop unused\n  return move present\n}\n",
