      '// Canonical completed typed outcome data. Failure rows project to ordinary value sums through\n// Row<! E>; Result itself remains ordinary source-defined data with no runtime row descriptor.\n\n/// The successful member of a completed outcome.\npub struct Success<A> {\n  /// The produced success value.\n  value: A\n}\n\n/// The failed member of a completed outcome.\npub struct Failure<F> {\n  /// The produced failure value.\n  error: F\n}\n\n/// One completed outcome: either a success carrying `A` or a failure carrying `F`.\n///\n/// `Result` is the reified form of an Effect that has already run. Reifying an Effect turns its\n/// failure row into ordinary value data, which is what lets the failure combinators in\n/// `silk.effects` be written as ordinary Silk source instead of compiler built-ins.\npub struct Result<A, F> {\n  /// The completed outcome, narrowed with `match`.\n  value: Success<A> | Failure<F>\n}\n\n/// Constructs a completed successful outcome.\npub fn succeed<A, F>(value: A) -> Result<A, F> {\n  return Result<A, F> { value: Success<A> { value: move value } }\n}\n\n/// Constructs a completed failed outcome.\npub fn failResult<A, F>(error: F) -> Result<A, F> {\n  return Result<A, F> { value: Failure<F> { error: move error } }\n}\n\n/// Applies a transform to a success value and carries a failure through unchanged.\npub fn map<A, B, F>(self: Result<A, F>, transform: once fn(A) -> B) -> Result<B, F> {\n  return match move self {\n    Result<A, F> { value: outcome } => match move outcome {\n      Success<A> { value } => succeed<B, F>(transform(move value))\n      Failure<F> { error } => failResult<B, F>(move error)\n    }\n  }\n}\n\n/// Applies a transform to a failure value and carries a success through unchanged.\npub fn mapError<A, F, G>(self: Result<A, F>, transform: once fn(F) -> G) -> Result<A, G> {\n  return match move self {\n    Result<A, F> { value: outcome } => match move outcome {\n      Success<A> { value } => succeed<A, G>(move value)\n      Failure<F> { error } => failResult<A, G>(transform(move error))\n    }\n  }\n}\n\n/// Continues a success with a transform that answers with a Result of its own, so the outcome\n/// stays one Result deep instead of nesting.\npub fn flatMap<A, B, F>(self: Result<A, F>, transform: once fn(A) -> Result<B, F>) -> Result<B, F> {\n  return match move self {\n    Result<A, F> { value: outcome } => match move outcome {\n      Success<A> { value } => transform(move value)\n      Failure<F> { error } => failResult<B, F>(move error)\n    }\n  }\n}\n\n/// Returns the success value, or the fallback value when the outcome is a failure.\n///\n/// Only the failure arm consumes the fallback. The success arm releases it, and the failure arm\n/// releases the error, so exactly one owned value leaves this call and the other drops.\npub fn unwrapOr<A, F>(self: Result<A, F>, fallback: A) -> A {\n  return match move self {\n    Result<A, F> { value: outcome } => match move outcome {\n      Success<A> { value } => keepSuccess<A>(move value, move fallback)\n      Failure<F> { error } => keepFallback<A, F>(move fallback, move error)\n    }\n  }\n}\n\n/// Answers whether the outcome succeeded, without consuming it.\npub fn isSuccess<A, F>(self: &Result<A, F>) -> bool {\n  return match &self.value {\n    Success<A> succeeded => true\n    Failure<F> failed => false\n  }\n}\n\n/// Answers whether the outcome failed, without consuming it.\npub fn isFailure<A, F>(self: &Result<A, F>) -> bool {\n  return match &self.value {\n    Success<A> succeeded => false\n    Failure<F> failed => true\n  }\n}\n\n/// Releases the fallback that a success value never needed. A match arm is one expression, so the\n/// arm that must both drop and produce delegates to this helper.\nfn keepSuccess<A>(success: A, unused: A) -> A {\n  drop unused\n  return move success\n}\n\n/// Releases the error the failure arm carried, and answers with the fallback it did need.\nfn keepFallback<A, F>(fallback: A, error: F) -> A {\n  drop error\n  return move fallback\n}\n',
